const body = $('Retell Tool Call').first().json.body || $('Retell Tool Call').first().json;
const fechaSolicitada = body.fecha;
const franjaSolicitada = body.franja;
const personasSolicitadas = parseInt(body.personas) || 1;
const CAPACIDAD_MAXIMA = 45;
const todasLasReservas = $input.all().map(item => item.json);
const estadosActivos = ['confirmada', 'en_espera', 'recordatorio_enviado'];
const reservasDelSlot = todasLasReservas.filter(r => {
  const fechaReserva = String(r['Fecha'] || '').trim();
  const franjaReserva = String(r['Franja'] || '').toLowerCase().trim();
  const estadoReserva = String(r['Estado'] || '').toLowerCase().trim();
  const fechaMatch = fechaReserva === fechaSolicitada || fechaReserva === fechaSolicitada.split('-').reverse().join('/');
  return fechaMatch && franjaReserva === franjaSolicitada && estadosActivos.includes(estadoReserva);
});
const personasOcupadas = reservasDelSlot.reduce((sum, r) => sum + (parseInt(r['Personas']) || 0), 0);
const personasDisponibles = CAPACIDAD_MAXIMA - personasOcupadas;
const disponible = personasDisponibles >= personasSolicitadas;
let proximaDisponible = null;
if (!disponible) {
  const fechaBase = new Date(fechaSolicitada);
  for (let d = 1; d <= 7; d++) {
    const fecha = new Date(fechaBase);
    fecha.setDate(fecha.getDate() + d);
    const diaSemana = fecha.getDay();
    if (diaSemana === 1) continue;
    const fechaStr = fecha.toISOString().split('T')[0];
    const reservasProximo = todasLasReservas.filter(r => {
      const fechaR = String(r['Fecha'] || '').trim();
      const franjaR = String(r['Franja'] || '').toLowerCase().trim();
      const estadoR = String(r['Estado'] || '').toLowerCase().trim();
      const fechaMatch = fechaR === fechaStr || fechaR === fechaStr.split('-').reverse().join('/');
      return fechaMatch && franjaR === franjaSolicitada && estadosActivos.includes(estadoR);
    });
    const personasProximo = reservasProximo.reduce((s, r) => s + (parseInt(r['Personas']) || 0), 0);
    const disponiblesProximo = CAPACIDAD_MAXIMA - personasProximo;
    if (disponiblesProximo >= personasSolicitadas) {
      const diasSemana = ['domingo', 'lunes', 'martes', 'mi�rcoles', 'jueves', 'viernes', 's�bado'];
      proximaDisponible = { fecha: fechaStr, franja: franjaSolicitada, personas_disponibles: disponiblesProximo, dia_semana: diasSemana[diaSemana] };
      break;
    }
  }
}
let mensaje;
if (disponible) {
  mensaje = `Disponibilidad confirmada para ${personasSolicitadas} personas`;
} else if (proximaDisponible) {
  const { dia_semana, fecha, franja } = proximaDisponible;
  const franjaProxTexto = franja === 'almuerzo' ? 'a mediod�a' : 'por la noche';
  mensaje = `Sin disponibilidad para esa fecha. El siguiente hueco disponible es el ${dia_semana} ${franjaProxTexto}`;
} else {
  mensaje = 'No hay disponibilidad en los pr�ximos d�as para esa franja. Prueba con otra franja u otro momento.';
}
return [{ json: { disponible, personas_disponibles: personasDisponibles > 0 ? personasDisponibles : 0, proxima_disponible: proximaDisponible, mensaje } }];

// Extrae datos del tool-call desde el payload de RETELL AI
// Retell envía: { name: "tool_name", args: {...}, call: {...} }
// El payload puede llegar directo en $json O anidado en $json.body

// Detectar si viene anidado o directo
const body = $input.item.json.body || $input.item.json;

// Verificar si es un tool-call de Retell
const isRetellToolCall = body.name && body.args !== undefined;

// Si no es tool-call, devolver vacío
if (!isRetellToolCall) {
  return [{ json: { toolName: '', toolCallId: '', args: {} } }];
}

const fn = body.name || '';
const args = body.args || {};
const callInfo = body.call || {};

// Teléfono del cliente
const callerPhone = callInfo.customer_number || body.customer_number || 'desconocido';
const callId = callInfo.id || body.call_id || '';

// NORMALIZACIÓN de campos
const personas = args.personas || args.comensales || args.num_personas || args.guests || null;
const nuevasPersonas = args.nuevas_personas || args.nuevos_comensales || args.nuevas_comensales || personas;

return [{
  json: {
    toolName: fn,
    toolCallId: body.tool_call_id || fn + '_' + Date.now(),
    args,
    // Campos normalizados
    nombre:         args.nombre || args.name || '',
    fecha:          args.fecha || args.date || '',
    hora:           args.hora || args.time || '',
    personas:       personas,
    telefono:       args.telefono || args.phone || callerPhone,
    nueva_fecha:    args.nueva_fecha || args.new_date || '',
    nueva_hora:     args.nueva_hora || args.new_time || '',
    nuevas_personas: nuevasPersonas,
    callerPhone,
    callId
  }
}];

// Calcular ventana de búsqueda en Calendar: ±90 min alrededor de la hora solicitada
// Construir fechas sin conversión de zona horaria para evitar problemas UTC
const d = $input.item.json;
const fecha = d.fecha;
const hora = d.hora;
const [hh, mm] = hora.split(':').map(Number);

// Construir fecha base en formato ISO sin conversión UTC
const baseStr = `${fecha}T${String(hh).padStart(2,'0')}:${String(mm).padStart(2,'0')}:00`;
const base = new Date(baseStr);

// Calcular ventanas de tiempo (±90 min)
const windowStartDate = new Date(base.getTime() - 90 * 60000);
const windowEndDate = new Date(base.getTime() + 90 * 60000);
const finReservaDate = new Date(base.getTime() + 90 * 60000);

// Formatear manualmente a ISO sin conversión UTC
const formatISO = (date) => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const hours = String(date.getHours()).padStart(2, '0');
  const minutes = String(date.getMinutes()).padStart(2, '0');
  const seconds = String(date.getSeconds()).padStart(2, '0');
  return `${year}-${month}-${day}T${hours}:${minutes}:${seconds}`;
};

const windowStart = formatISO(windowStartDate);
const windowEnd = formatISO(windowEndDate);
const inicioReserva = baseStr;
const finReserva = formatISO(finReservaDate);

return [{ json: { ...d, windowStart, windowEnd, inicioReserva, finReserva } }];

const events = $input.all().map(i => i.json);
const base = $node['Preparar ventana horaria'].json;

let personasOcupadas = 0;
let mesasOcupadas = 0;
for (const ev of events) {
  const match = ev.summary?.match(/(\d+)\s*(personas?|comensales?)/i);
  if (match) { personasOcupadas += parseInt(match[1]); mesasOcupadas++; }
}

const AFORO_MAX = 40;
const MESAS_MAX = 10;
const personasSolicitadas = parseInt(base.personas) || 1;
const personasLibres = AFORO_MAX - personasOcupadas;
const mesasLibres = MESAS_MAX - mesasOcupadas;
const disponible = personasSolicitadas <= personasLibres && mesasLibres > 0;

return [{ json: { ...base, personasOcupadas, mesasOcupadas, personasLibres, mesasLibres, disponible, personasSolicitadas } }];

