const d = $input.item.json;
const [hh, mm] = d.nueva_hora.split(':').map(Number);
// Construct date with explicit timezone to avoid 1-hour shift
const base = new Date(`${d.nueva_fecha}T${String(hh).padStart(2,'0')}:${String(mm).padStart(2,'0')}:00.000Z`);
const windowStart = new Date(base.getTime() - 90 * 60000).toISOString();
const windowEnd   = new Date(base.getTime() + 90 * 60000).toISOString();
return [{ json: { ...d, windowStart, windowEnd } }];

const events = $input.all().map(i => i.json);
const base = $node['Ventana modificación'].json;
let personasOcupadas = 0;
let mesasOcupadas = 0;
for (const ev of events) {
  const match = ev.summary?.match(/(\d+)\s*(personas?|comensales?)/i);
  if (match) { personasOcupadas += parseInt(match[1]); mesasOcupadas++; }
}
const AFORO_MAX = 40;
const MESAS_MAX = 10;
const p = parseInt(base.nuevas_personas) || 1;
const disponible = p <= (AFORO_MAX - personasOcupadas) && mesasOcupadas < MESAS_MAX;
return [{ json: { ...base, personasOcupadas, mesasOcupadas, disponible } }];

const row = $input.item.json;
const modif = $node['Calcular disp. modificación'].json;
const [hh, mm] = modif.nueva_hora.split(':');

// Construct dates with explicit timezone to avoid 1-hour shift
const fechaStr = `${modif.nueva_fecha}T${String(hh).padStart(2,'0')}:${String(mm).padStart(2,'0')}:00`;
const inicio = new Date(fechaStr);
const fin = new Date(inicio.getTime() + 90 * 60000);

// Format as ISO string but preserve local time by removing timezone offset
const formatLocalISO = (date) => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const hours = String(date.getHours()).padStart(2, '0');
  const minutes = String(date.getMinutes()).padStart(2, '0');
  const seconds = String(date.getSeconds()).padStart(2, '0');
  return `${year}-${month}-${day}T${hours}:${minutes}:${seconds}`;
};

return [{ json: {
  ...modif,
  calendarId: row['ID Evento Calendar'] || '',
  fechaInicio: formatLocalISO(inicio),
  fechaFin: formatLocalISO(fin),
