// ===================================================================
// INYECTOR DE VARIABLES DINÁMICAS PARA RETELL AI
// ===================================================================

const now = new Date();

// Formatear fecha en español
const optionsFecha = {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  timeZone: 'Europe/Madrid'
};

const optionsHora = {
  hour: '2-digit',
  minute: '2-digit',
  timeZone: 'Europe/Madrid'
};

const current_date = now.toLocaleDateString('es-ES', optionsFecha);
const current_time = now.toLocaleTimeString('es-ES', optionsHora);
const day_of_week = now.toLocaleDateString('es-ES', { weekday: 'long', timeZone: 'Europe/Madrid' });
const day_of_week_cap = day_of_week.charAt(0).toUpperCase() + day_of_week.slice(1);

// Obtener datos del input (webhook de Retell) - DIRECTAMENTE, sin anidar
const inputData = $input.item.json;

// Devolver todo junto - MANTENER los datos originales de Retell
return [{
  json: {
    // MANTENER datos originales de Retell (CRÍTICO para el extractor)
    name: inputData.name,
    args: inputData.args,
    call: inputData.call,
    call_id: inputData.call_id,
    customer_number: inputData.customer_number,
    // Variables dinámicas para el prompt
    dynamic_variables: {
      current_date: current_date,
      current_time: current_time,
      day_of_week: day_of_week_cap
    },
    // También disponibles como campos directos
    fecha_actual: current_date,
    hora_actual: current_time,
    dia_semana: day_of_week_cap,
    timestamp: now.toISOString()
  }
}];

// ===================================================================
// EXTRACTOR DE TOOL-CALL PARA RETELL AI - VERSIÓN CORREGIDA
// ===================================================================
// Formato Retell: { name, args, call } en la RAÍZ del JSON
// NO viene anidado en "body" ni en "message"
// ===================================================================

// El payload de Retell llega DIRECTAMENTE en $input.item.json
const data = $input.item.json;

// Debug: ver qué llega realmente
console.log('=== PAYLOAD RECIBIDO ===');
console.log('Keys:', Object.keys(data));
console.log('name:', data.name);
console.log('args:', JSON.stringify(data.args));

// Extraer name y args directamente de la raíz
const toolName = data.name || '';
const args = data.args || data.parameters || {};

// Verificar si es un tool-call válido
const isToolCall = toolName && (Object.keys(args).length > 0 || data.args !== undefined);

if (!isToolCall) {
  return [{
    json: {
      isToolCall: false,
      toolName: '',
      args: {},
      callId: data.call_id || data.call?.id || '',
      callerPhone: data.customer_number || data.call?.customer_number || '',
      rawPayload: data
    }
  }];
}

// Extraer información del call
const callInfo = data.call || {};
const callerPhone = callInfo.customer_number || data.customer_number || 'desconocido';
const callId = callInfo.id || data.call_id || '';

// NORMALIZACIÓN de campos
const personas = args.personas || args.comensales || args.num_personas || args.guests || null;
const nuevasPersonas = args.nuevas_personas || args.nuevos_comensales || args.nuevasPersonas || personas;

return [{
  json: {
    isToolCall: true,
    toolName: toolName,
    toolCallId: data.tool_call_id || toolName + '_' + Date.now(),
    args: args,
    // Campos normalizados
    nombre: args.nombre || args.name || args.cliente || '',
    fecha: args.fecha || args.date || args.dia || '',
    hora: args.hora || args.time || args.horario || '',
    personas: personas,
    telefono: args.telefono || args.phone || args.telf || callerPhone,
    nueva_fecha: args.nueva_fecha || args.new_date || '',
    nueva_hora: args.nueva_hora || args.new_time || '',
    nuevas_personas: nuevasPersonas,
    // Info del caller
    callerPhone: callerPhone,
    callId: callId,
    // Raw para debug
    rawPayload: data
  }
}];

