// Calcular ventana de búsqueda en Calendar: ±90 min alrededor de la hora
const d = $input.item.json;
const fecha = d.fecha;
const hora = d.hora;

// Validar datos básicos
if (!fecha || !hora) {
  return [{
    json: {
      ...d,
      error: 'Falta fecha u hora',
      ventanaValida: false
    }
  }];
}

const [hh, mm] = hora.split(':').map(Number);

// Construir fecha en formato ISO (hora local)
const baseStr = `${fecha}T${String(hh).padStart(2,'0')}:${String(mm).padStart(2,'0')}:00`;
const base = new Date(baseStr);

// Ventana ±90 minutos
const windowStart = new Date(base.getTime() - 90 * 60000);
const windowEnd = new Date(base.getTime() + 90 * 60000);
const finReserva = new Date(base.getTime() + 90 * 60000);

// Formatear sin conversión de timezone
const formatISO = (date) => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const hours = String(date.getHours()).padStart(2, '0');
  const minutes = String(date.getMinutes()).padStart(2, '0');
  const seconds = String(date.getSeconds()).padStart(2, '0');
  return `${year}-${month}-${day}T${hours}:${minutes}:${seconds}`;
};

return [{
  json: {
    ...d,
    ventanaValida: true,
    windowStart: formatISO(windowStart),
    windowEnd: formatISO(windowEnd),
    inicioReserva: baseStr,
    finReserva: formatISO(finReserva)
  }
}];

// Calcular disponibilidad basada en eventos de Calendar
const events = $input.all().map(i => i.json);
const base = $node['Preparar Ventana - Crear'].json;

let personasOcupadas = 0;
let mesasOcupadas = 0;

for (const ev of events) {
  // Extraer número de personas del título del evento
  const match = ev.summary?.match(/(\d+)\s*(personas?|comensales?)/i);
  if (match) {
    personasOcupadas += parseInt(match[1]);
    mesasOcupadas++;
  }
}

// Configuración del restaurante
const AFORO_MAX = 40;
const MESAS_MAX = 10;

const personasSolicitadas = parseInt(base.personas) || 1;
const personasLibres = AFORO_MAX - personasOcupadas;
const mesasLibres = MESAS_MAX - mesasOcupadas;
const disponible = personasSolicitadas <= personasLibres && mesasLibres > 0;

return [{
  json: {
    ...base,
    personasOcupadas,
    mesasOcupadas,
    personasLibres,
    mesasLibres,
    disponible,
    personasSolicitadas
  }
}];

