const diasSemana  = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const diaSemana   = diasSemana[new Date(fecha).getDay()];
const ahora       = new Date().toISOString().replace('T',' ').substring(0,19);

return [{ json: {
  encontrado: true,
  calEventId: reserva['Calendar_Event_ID'] || '',
  idReserva:  reserva['ID_Reserva'] || '',
  telefono,
  historialFila: {
    ID_Reserva:           reserva['ID_Reserva'] || '',
    Fecha:                reserva['Fecha'] || '',
    Franja:               reserva['Franja'] || '',
    Nombre:               reserva['Nombre'] || '',
    Telefono:             reserva['Teléfono'] || reserva['Telefono'] || '',
    Personas:             reserva['Personas'] || '',
    Estado:               'cancelada',
    Notas:                reserva['Notas'] || '',
    Fecha_Creacion:       reserva['Fecha_Creación'] || reserva['Fecha_Creacion'] || '',
    Fecha_Modificacion:   ahora,
    Call_ID:              reserva['Call_ID'] || '',
    Origen:               reserva['Origen'] || 'telefono',
    Recordatorio_Enviado: reserva['Recordatorio_Enviado'] || 'no',
    Calendar_Event_ID:    reserva['Calendar_Event_ID'] || '',
    Estado_Final:         'cancelada_cliente',
    Motivo_Cancelacion:   'cliente llamó',
    Fecha_Cancelacion:    ahora
  },
  resumen: `Reserva de ${apellido} del ${diaSemana} ${franjaTexto} cancelada correctamente`
}}];

const raw = $('Retell Tool Call').first().json.body || $('Retell Tool Call').first().json;
  let body;
  if (raw.arguments !== undefined) {
    body = typeof raw.arguments === 'string' ? JSON.parse(raw.arguments) : raw.arguments;
  } else {
    body = raw;
  }

const nombre   = String(body.nombre   || '').trim();
const telefono = String(body.telefono || '').trim();
const personas = parseInt(body.personas) || 0;
const fecha    = String(body.fecha    || '').trim(); // yyyy-mm-dd
const franja   = String(body.franja   || '').trim(); // almuerzo | cena
const notas    = String(body.notas    || '').trim();

if (!nombre || !telefono || !personas || !fecha || !franja) {
  return [{ json: { error: true, mensaje: 'Faltan datos para crear la reserva.' } }];
}

// ID de reserva
const fechaCompacta = fecha.replace(/-/g, '');
const inicialFranja = franja === 'almuerzo' ? 'A' : 'C';
const aleatorio     = Math.random().toString(36).toUpperCase().substring(2, 6);
const idReserva     = `${fechaCompacta}${inicialFranja}-${aleatorio}`;

// Fecha formateada para Sheets (dd/mm/yyyy)
const [year, month, day] = fecha.split('-');
const fechaFormateada = `${day}/${month}/${year}`;

// Fechas-hora para Google Calendar (formato ISO 8601 con zona horaria)
// Almuerzo: 13:30 - 16:00 | Cena: 20:30 - 23:59
const horaInicio = franja === 'almuerzo' ? '13:30:00' : '20:30:00';
const horaFin    = franja === 'almuerzo' ? '16:00:00' : '23:59:00';
const fechaHoraInicio = `${fecha}T${horaInicio}`;
const fechaHoraFin    = `${fecha}T${horaFin}`;

// Título y descripción del evento de calendario
const apellido  = nombre.split(' ').pop();
const tituloEvento = `Ekis — ${apellido} (${personas} pers.) — ${franja}`;
const descripcion  = `Reserva ID: ${idReserva}\nNombre: ${nombre}\nTeléfono: ${telefono}\nPersonas: ${personas}\nFranja: ${franja}${notas ? '\nNotas: ' + notas : ''}`;

// Texto natural para confirmar a Carmen
const diasSemana = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const diaSemana  = diasSemana[new Date(fecha).getDay()];
const franjaTexto = franja === 'almuerzo' ? 'a mediodía' : 'por la noche';
const mensajeConfirmacion = `Reserva confirmada a nombre de ${apellido}, para ${personas} ${personas === 1 ? 'persona' : 'personas'}, el ${diaSemana} ${franjaTexto}. Te esperamos.`;

const ahora = new Date().toISOString().replace('T', ' ').substring(0, 19);

return [{ json: {
  error: false,
  idReserva, nombre, apellido, telefono, personas, fecha, franja, notas,
  fechaFormateada,
  fechaHoraInicio, fechaHoraFin,
  tituloEvento, descripcion,
  mensajeConfirmacion,
  ahora
}}];

const raw = $('Retell Tool Call').first().json.body || $('Retell Tool Call').first().json;
  let body;
  if (raw.arguments !== undefined) {
    body = typeof raw.arguments === 'string' ? JSON.parse(raw.arguments) : raw.arguments;
  } else {
    body = raw;
  }

const telefono   = String(body.telefono    || '').trim();
const fechaActual = String(body.fecha_actual || '').trim();
const nuevaFecha  = body.nueva_fecha   ? String(body.nueva_fecha).trim()  : null;
const nuevaFranja = body.nueva_franja  ? String(body.nueva_franja).trim() : null;
const nuevasPersonas = body.nuevas_personas ? parseInt(body.nuevas_personas) : null;

if (!telefono || !fechaActual) {
  return [{ json: { encontrado: false, resumen_nuevo: 'Necesito el teléfono y la fecha actual de la reserva.' } }];
}

const [ya, ma, da] = fechaActual.split('-');
const fechaFormateadaBusqueda = `${da}/${ma}/${ya}`;

const reservas = $input.all().map(item => item.json);

const reserva = reservas.find(r => {
  const tel = String(r['Teléfono'] || r['Telefono'] || '').replace(/\s/g, '');
  const fechaR = String(r['Fecha'] || '').trim();
  const estado = String(r['Estado'] || '').toLowerCase();
  const activo = ['confirmada','en_espera','recordatorio_enviado'].includes(estado);
  const telOk  = tel === telefono.replace(/\s/g, '');
  const fechaOk = fechaR === fechaActual || fechaR === fechaFormateadaBusqueda;
  return telOk && fechaOk && activo;
});

if (!reserva) {
  return [{ json: {
    encontrado: false,
    resumen_nuevo: `No encuentro ninguna reserva activa para ese teléfono el ${fechaFormateadaBusqueda}. ¿Puede que sea en otra fecha?`
  }}];
}

// Valores finales tras la modificación
const fechaFinal    = nuevaFecha   || fechaActual;
const franjaFinal   = nuevaFranja  || String(reserva['Franja'] || '');
const personasFinal = nuevasPersonas || parseInt(reserva['Personas']) || 0;
const calEventId    = reserva['Calendar_Event_ID'] || '';
const nombre        = reserva['Nombre'] || '';
const apellido      = nombre.split(' ').pop() || nombre;

// Fecha formateada para Sheets
let fechaFinalFormateada;
if (nuevaFecha) {
  const [ny, nm, nd] = nuevaFecha.split('-');
  fechaFinalFormateada = `${nd}/${nm}/${ny}`;
} else {
  fechaFinalFormateada = reserva['Fecha'];
}

// Fechas-hora para Calendar
const horaInicio = franjaFinal === 'almuerzo' ? '13:30:00' : '20:30:00';
const horaFin    = franjaFinal === 'almuerzo' ? '16:00:00' : '23:59:00';
const fechaHoraInicio = `${fechaFinal}T${horaInicio}`;
const fechaHoraFin    = `${fechaFinal}T${horaFin}`;
const tituloEvento    = `Ekis — ${apellido} (${personasFinal} pers.) — ${franjaFinal} [MODIFICADA]`;

// Mensaje para Carmen
const diasSemana  = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const diaSemana   = diasSemana[new Date(fechaFinal).getDay()];
const franjaTexto = franjaFinal === 'almuerzo' ? 'a mediodía' : 'por la noche';
const ahora = new Date().toISOString().replace('T',' ').substring(0,19);

return [{ json: {
  encontrado:    true,
  calEventId,
  fechaFinal, fechaFinalFormateada, franjaFinal, personasFinal,
  fechaHoraInicio, fechaHoraFin, tituloEvento,
  telefono,
  idReserva:  reserva['ID_Reserva'] || '',
  ahora,
  resumen_nuevo: `Reserva de ${apellido} actualizada: ${diaSemana} ${franjaTexto}, ${personasFinal} personas`
}}];

// Parámetros recibidos de Retell
const raw = $('Retell Tool Call').first().json.body || $('Retell Tool Call').first().json;
  let body;
  if (raw.arguments !== undefined) {
    body = typeof raw.arguments === 'string' ? JSON.parse(raw.arguments) : raw.arguments;
  } else {
    body = raw;
  }
const fechaSolicitada = body.fecha;   // '2026-04-15'
const franjaSolicitada = body.franja; // 'almuerzo' | 'cena'
const personasSolicitadas = parseInt(body.personas) || 1;

// Capacidad máxima del restaurante (45 en sala)
const CAPACIDAD_MAXIMA = 45;

// Leer todas las reservas activas
const todasLasReservas = $input.all().map(item => item.json);

// Filtrar por fecha + franja + estado activo
const estadosActivos = ['confirmada', 'en_espera', 'recordatorio_enviado'];
const reservasDelSlot = todasLasReservas.filter(r => {
  const fechaReserva = String(r['Fecha'] || '').trim();
  const franjaReserva = String(r['Franja'] || '').toLowerCase().trim();
  const estadoReserva = String(r['Estado'] || '').toLowerCase().trim();

  // La fecha en Sheets puede ser 'dd/mm/yyyy' o 'yyyy-mm-dd'
  // Comparamos directamente contra ambos formatos
  const fechaMatch = fechaReserva === fechaSolicitada || 
    fechaReserva === fechaSolicitada.split('-').reverse().join('/');

  return fechaMatch && franjaReserva === franjaSolicitada && estadosActivos.includes(estadoReserva);
});

// Sumar personas ya reservadas en ese slot
const personasOcupadas = reservasDelSlot.reduce((sum, r) => {
  return sum + (parseInt(r['Personas']) || 0);
}, 0);

const personasDisponibles = CAPACIDAD_MAXIMA - personasOcupadas;
const disponible = personasDisponibles >= personasSolicitadas;

// Buscar próximo slot disponible si no hay para el solicitado
let proximaDisponible = null;
if (!disponible) {
  // Buscar en los próximos 7 días, mismo franja
  const fechaBase = new Date(fechaSolicitada);
  for (let d = 1; d <= 7; d++) {
    const fecha = new Date(fechaBase);
    fecha.setDate(fecha.getDate() + d);

    // Saltar lunes (día 1 = lunes en getDay, 0 = domingo)
    const diaSemana = fecha.getDay();
    if (diaSemana === 1) continue; // Lunes: cerrado

    const fechaStr = fecha.toISOString().split('T')[0]; // 'yyyy-mm-dd'

    const reservasProximo = todasLasReservas.filter(r => {
      const fechaR = String(r['Fecha'] || '').trim();
      const franjaR = String(r['Franja'] || '').toLowerCase().trim();
      const estadoR = String(r['Estado'] || '').toLowerCase().trim();
      const fechaMatch = fechaR === fechaStr || 
        fechaR === fechaStr.split('-').reverse().join('/');
      return fechaMatch && franjaR === franjaSolicitada && estadosActivos.includes(estadoR);
    });

    const personasProximo = reservasProximo.reduce((s, r) => s + (parseInt(r['Personas']) || 0), 0);
    const disponiblesProximo = CAPACIDAD_MAXIMA - personasProximo;

    if (disponiblesProximo >= personasSolicitadas) {
      const diasSemana = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
      proximaDisponible = {
        fecha: fechaStr,
        franja: franjaSolicitada,
        personas_disponibles: disponiblesProximo,
        dia_semana: diasSemana[diaSemana]
      };
      break;
    }
  }
}

// Construir mensaje en lenguaje natural para Carmen
const franjaTexto = franjaSolicitada === 'almuerzo' ? 'al mediodía' : 'por la noche';
let mensaje;
if (disponible) {
  mensaje = `Disponibilidad confirmada para ${personasSolicitadas} personas`;
} else if (proximaDisponible) {
  const { dia_semana, fecha, franja } = proximaDisponible;
  const franjaProxTexto = franja === 'almuerzo' ? 'a mediodía' : 'por la noche';
  mensaje = `Sin disponibilidad para esa fecha. El siguiente hueco disponible es el ${dia_semana} ${franjaProxTexto}`;
} else {
  mensaje = `No hay disponibilidad en los próximos días para esa franja. Prueba con otra franja u otro momento.`;
}

return [{
  json: {
    disponible,
    personas_disponibles: personasDisponibles > 0 ? personasDisponibles : 0,
    proxima_disponible: proximaDisponible,
    mensaje
  }
}];

const args = $input.item.json.args;
const fecha = args.fecha;
const hora = args.hora;
const [hh, mm] = hora.split(':').map(Number);
const base = new Date(`${fecha}T${String(hh).padStart(2,'0')}:${String(mm).padStart(2,'0')}:00`);
const windowStart = new Date(base.getTime() - 90 * 60000).toISOString();
const windowEnd   = new Date(base.getTime() + 90 * 60000).toISOString();
const inicioReserva = base.toISOString();
const finReserva    = new Date(base.getTime() + 90 * 60000).toISOString();
return [{ json: { ...$input.item.json, windowStart, windowEnd, inicioReserva, finReserva, fecha, hora, personas: args.personas, nombre: args.nombre, telefono: args.telefono || $input.item.json.callerPhone } }];

const events = $input.all().map(i => i.json);
const base = $node['Preparar ventana horaria'].json;
let personasOcupadas = 0;
let mesasOcupadas = 0;
for (const ev of events) {
  const match = ev.summary?.match(/(\d+)\s*persona/);
  if (match) { personasOcupadas += parseInt(match[1]); mesasOcupadas++; }
}
const AFORO_MAX = 40;
const MESAS_MAX = 10;
const personasSolicitadas = parseInt(base.personas) || 1;
const personasLibres = AFORO_MAX - personasOcupadas;
const mesasLibres = MESAS_MAX - mesasOcupadas;
const disponible = personasSolicitadas <= personasLibres && mesasLibres > 0;
return [{ json: { ...base, personasOcupadas, mesasOcupadas, personasLibres, mesasLibres, disponible, personasSolicitadas } }];

