const d = $input.item.json;
const [hh, mm] = d.hora.split(':');

// Construir fechas con timezone explícito para evitar conversión UTC
const fechaBase = d.fecha; // formato YYYY-MM-DD
const horaFormateada = `${String(hh).padStart(2,'0')}:${String(mm).padStart(2,'0')}:00`;

// Crear ISO strings directamente con timezone +01:00
const fechaInicio = `${fechaBase}T${horaFormateada}+01:00`;

// Calcular fin (90 minutos después) manteniendo el mismo día
const totalMinutos = hh * 60 + mm + 90;
const hhFin = Math.floor(totalMinutos / 60);
const mmFin = totalMinutos % 60;
const horaFin = `${String(hhFin).padStart(2,'0')}:${String(mmFin).padStart(2,'0')}:00`;
const fechaFin = `${fechaBase}T${horaFin}+01:00`;

return [{ json: {
  ...d,
  eventoTitulo: `Reserva - ${d.nombre} (${d.personas} personas)`,
  eventoDescripcion: `Nombre: ${d.nombre}\nPersonas: ${d.personas}\nTeléfono: ${d.telefono}\nOrigen: Llamada IA`,
  fechaInicio: fechaInicio,
  fechaFin: fechaFin
} }];

