const fechaStr = `${d.fecha}T${String(hh).padStart(2,'0')}:${String(mm).padStart(2,'0')}:00+01:00`;
const base = new Date(fechaStr);

const windowStart = new Date(base.getTime() - 90 * 60000).toISOString();
const windowEnd   = new Date(base.getTime() + 90 * 60000).toISOString();

return [{ json: { ...d, windowStart, windowEnd } }];

const events = $input.all().map(i => i.json);
const base = $node['Preparar verificación'].json;
let personasOcupadas = 0;
let mesasOcupadas = 0;
for (const ev of events) {
  const match = ev.summary?.match(/(\d+)\s*(personas?|comensales?)/i);
  if (match) { personasOcupadas += parseInt(match[1]); mesasOcupadas++; }
}
const AFORO_MAX = 40;
const MESAS_MAX = 10;
const p = parseInt(base.personas) || 1;
const personasLibres = AFORO_MAX - personasOcupadas;
const mesasLibres = MESAS_MAX - mesasOcupadas;
const disponible = p <= personasLibres && mesasLibres > 0;
return [{ json: { ...base, personasOcupadas, mesasOcupadas, personasLibres, mesasLibres, disponible } }];

